const crypto = require('crypto');
const fs = require('fs');

// L'archivio e gia stato scritto dal nodo precedente: l'impronta si calcola
// rileggendolo dal disco a blocchi di quattro megabyte, cosi la memoria
// occupata non dipende dalla sua dimensione. E anche piu fedele, perche
// certifica il file che la normalizzazione rileggera e non una copia
// intermedia tenuta in memoria.
const oggi = $now.toFormat('yyyy-MM-dd');
const fileName = `malwarebazaar_${oggi}.zip`;
const percorso = `/data/raw/${fileName}`;

const impronta = crypto.createHash('sha256');
const flusso = fs.createReadStream(percorso, { highWaterMark: 4 * 1024 * 1024 });
await new Promise((completa, fallisci) => {
  flusso.on('data', blocco => impronta.update(blocco));
  flusso.on('end', completa);
  flusso.on('error', fallisci);
});

return [{
  json: {
    source: 'MalwareBazaar',
    url: 'https://bazaar.abuse.ch/export/csv/full/',
    fetchedAt: $now.toISO(),
    fileName,
    sha256: impronta.digest('hex'),
    sizeBytes: fs.statSync(percorso).size
  }
}];

