const crypto = require('crypto');
const fs = require('fs');

// Il manifest descrive i file davvero presenti nella cartella delle acquisizioni,
// non quelli annunciati dai rami del flusso. Cosi non dipende dall'ordine in cui
// i rami terminano, e soprattutto l'impronta certifica il contenuto scritto su
// disco, che e esattamente quello che la normalizzazione poi rilegge.
const CARTELLA = '/data/raw';

// Il prefisso del nome file dice da quale fonte proviene. Sono ordinati dal piu
// lungo al piu corto, altrimenti otx_subscribed verrebbe riconosciuto come otx.
const FONTI = {
  otx_subscribed: {
    source: 'AlienVault OTX (subscribed)',
    url: 'https://otx.alienvault.com/api/v1/pulses/subscribed?limit=50',
  },
  malwarebazaar: {
    source: 'MalwareBazaar',
    url: 'https://bazaar.abuse.ch/export/csv/full/',
  },
  mitre_attack: {
    source: 'MITRE ATT&CK',
    url: 'https://raw.githubusercontent.com/mitre-attack/attack-stix-data/v19.2/enterprise-attack/enterprise-attack.json',
  },
  threatfox: {
    source: 'ThreatFox',
    url: 'https://threatfox.abuse.ch/export/json/full/',
  },
  malpedia: {
    source: 'Malpedia',
    url: 'https://malpedia.caad.fkie.fraunhofer.de/api/get/families',
  },
  urlhaus: {
    source: 'URLhaus',
    url: 'https://urlhaus.abuse.ch/downloads/json/',
  },
};

const oggi = $now.toFormat('yyyy-MM-dd');
const prefissi = Object.keys(FONTI).sort((a, b) => b.length - a.length);
const sources = [];

for (const nome of fs.readdirSync(CARTELLA).sort()) {
  if (nome.startsWith('manifest_') || !nome.includes(oggi)) continue;

  const prefisso = prefissi.find((chiave) => nome.startsWith(chiave));
  if (!prefisso) continue;

  const percorso = `${CARTELLA}/${nome}`;
  const impronta = crypto.createHash('sha256');
  const flusso = fs.createReadStream(percorso, { highWaterMark: 4 * 1024 * 1024 });
  await new Promise((completa, fallisci) => {
    flusso.on('data', (blocco) => impronta.update(blocco));
    flusso.on('end', completa);
    flusso.on('error', fallisci);
  });

  const informazioni = fs.statSync(percorso);
  sources.push({
    source: FONTI[prefisso].source,
    url: FONTI[prefisso].url,
    fetchedAt: informazioni.mtime.toISOString(),
    fileName: nome,
    sha256: impronta.digest('hex'),
    sizeBytes: informazioni.size,
  });
}

if (sources.length === 0) {
  throw new Error(`Nessuna acquisizione datata ${oggi} in ${CARTELLA}.`);
}

const testo = JSON.stringify({ generatedAt: $now.toISO(), sources }, null, 2);

return [{
  json: { fonti: sources.length },
  binary: {
    data: {
      data: Buffer.from(testo, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'manifest.json',
    },
  },
}];

const crypto = require('crypto');

// Con la paginazione n8n restituisce un elemento per pagina: i risultati vanno
// riuniti in un unico oggetto, nella stessa forma in cui l'API li restituirebbe
// se stessero in una pagina sola, perche e quella che la normalizzazione legge.
const pagine = $input.all().map(elemento => elemento.json);
const risultati = pagine.flatMap(pagina => pagina.results || []);
const unito = { count: risultati.length, results: risultati };

const data = JSON.stringify(unito, null, 2);
const sha256 = crypto.createHash('sha256').update(data, 'utf8').digest('hex');
const binary = Buffer.from(data, 'utf8').toString('base64');
const today = $now.toFormat('yyyy-MM-dd');  // stesso fuso dei nodi che scrivono i file
const fileName = `otx_subscribed_${today}.json`;

return [{
  json: {
source: 'AlienVault OTX (subscribed)',
    url: 'https://otx.alienvault.com/api/v1/pulses/subscribed?limit=50',
    fetchedAt: $now.toISO(),
    fileName,
    sha256,
    sizeBytes: Buffer.byteLength(data, 'utf8')
  },
  binary: {
    data: { data: binary, mimeType: 'application/json', fileName }
  }
}];
